            if v == 3 and ((r < h // 2 and c >= 8) or (r < h // 2 and c <= 11)):
                # Recolor only cells in the connected 3 component spanning the
                # middle upper area, omitting isolated 3s elsewhere.
                pass
    # The target is the 3 glyph with several cells located in the upper-middle
    # region; find connected 3 components and recolor those.
    seen = set()
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
