                    if (0 <= nx < h and 0 <= ny < len(grid[nx]) and
                            (nx, ny) not in seen and grid[nx][ny] == 3):
                        seen.add((nx, ny)); stack.append((nx, ny))
            if len(comp) >= 4 and min(x for x, _ in comp) <= 8 and max(x for x, _ in comp) >= 5:
                for x, y in comp:
                    out[x][y] = 7
    return out
